     3	 * (TASK-THYROX-0729). El dominio dice «instala este modelo contractual desde
     4	 * este GGUF verificado, con este digest»; cómo lo hace un runtime concreto
     5	 * (en Ollama, `/api/blobs` y `/api/create`) vive sólo en su adapter.
     6	 *
     7	 * `inspect` devuelve el CONTENIDO que el runtime tiene bajo el nombre, no su
     8	 * presencia: un nombre listado con otro blob no es el modelo pedido.
     9	 */
    10	
    11	/** Lo que el runtime sirve hoy bajo un nombre contractual. */
    12	export interface InstalledModelState {
    13	  readonly name: string
    14	  /** sha256 (64 hex) del blob GGUF que el runtime resuelve para el nombre. */
    15	  readonly contentSha256: string
    16	}
    17	
    18	export interface ModelInstallRequest {
    19	  /** Nombre contractual del catálogo. */
    20	  readonly name: string
    21	  /** GGUF verificado en la caché local. */
    22	  readonly artifactPath: string
    23	  /** sha256 (64 hex) que el runtime tiene que guardar. */
    24	  readonly contentSha256: string
    25	}
    26	
    27	export type InstallOutcome =
    28	  | { readonly status: 'installed' }
    29	  | { readonly status: 'failed'; readonly reason: string }
    30	
    31	export interface ModelInstaller {
    32	  /** `undefined` si el runtime no resuelve el nombre. */
    33	  inspect(name: string): Promise<InstalledModelState | undefined>
    34	  install(request: ModelInstallRequest): Promise<InstallOutcome>
    35	}

  1	/**
  2	 * `ensureModel(name, deps)`: el reconciliador idempotente que deja disponible
  3	 * un modelo del catálogo en un runtime (TASK-THYROX-0729). No es
  4	 * `download()+install()`: cada paso mide el estado y actúa sólo si no es el
  5	 * pedido, así que la segunda llamada no descarga ni instala.
  6	 *
  7	 * Responde una sola pregunta —¿puede este runtime servir este modelo
  8	 * concreto?—. No decide GPU, instancia, residencia ni endpoint
  9	 * (TASK-THYROX-0703).
 10	 *
 11	 * READY exige tres digests iguales, cada uno medido: el sha256 del catálogo,
 12	 * el del GGUF materializado (el que `materializeArtifact` midió sobre el
 13	 * archivo antes de publicarlo en la caché) y el contenido que el runtime resuelve para el nombre después de
 14	 * cualquier instalación. Un instalador que responde `installed` y sirve otra
 15	 * cosa no deja READY. `downloaded` e `installed` dicen lo que ocurrió en esta
 16	 * llamada, no lo que se supone.
 17	 */
 18	import type { CatalogArtifact, ModelCatalogEntry } from '@thyrox/model-artifacts/catalogEntry.ts'
 19	import type { ModelArtifactResolver, PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'
 20	
 21	import { materializeArtifact, type ArtifactFetcher } from './modelArtifactCache.js'
 22	import type { InstalledModelState, ModelInstaller } from './modelInstaller.js'
 23	
 24	/** La parte del catálogo que el reconciliador consulta. */
 25	export interface CatalogLookup {
 26	  byName(name: string): ModelCatalogEntry | undefined
 27	}
 28	
 29	export interface EnsureModelDependencies {
 30	  readonly catalog: CatalogLookup
 31	  readonly resolver: ModelArtifactResolver
 32	  readonly fetcher: ArtifactFetcher
 33	  readonly installer: ModelInstaller
 34	  readonly cacheDir: string
 35	}
 36	
 37	/** Los tres digests cuya igualdad es READY. */
 38	export interface ReadinessEvidence {
 39	  readonly catalogSha256: string
 40	  readonly materializedSha256: string
 41	  /** Vacío si el runtime no resuelve el nombre: nunca coincide con un sha256. */
 42	  readonly runtimeSha256: string
 43	}
 44	
 45	/** Dónde se detuvo una reconciliación fallida. */
 46	export type EnsureStage = 'materialize' | 'install' | 'verify'
 47	
 48	export type EnsureOutcome =
 49	  | { readonly status: 'ready'; readonly name: string; readonly evidence: ReadinessEvidence; readonly downloaded: boolean; readonly installed: boolean }
 50	  | { readonly status: 'not_declared'; readonly name: string }
 51	  | { readonly status: 'not_materializable'; readonly name: string; readonly reason: string }
 52	  | { readonly status: 'failed'; readonly name: string; readonly stage: EnsureStage; readonly reason: string; readonly downloaded: boolean; readonly installed: boolean }
 53	
 54	/** Un GGUF verificado en la caché y lo que costó tenerlo. */
 55	interface Materialized {
 56	  readonly path: string
 57	  readonly sha256: string
 58	  readonly downloaded: boolean
 59	}
 60	
 61	/** Lo que el runtime resuelve tras reconciliar, y si hubo que instalar. */
 62	interface Reconciled {
 63	  readonly state: InstalledModelState | undefined
 64	  readonly installed: boolean
 65	}
 66	
 67	type StepResult<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly reason: string }
 68	
 69	export async function ensureModel(name: string, deps: EnsureModelDependencies): Promise<EnsureOutcome> {
 70	  const entry = deps.catalog.byName(name)
 71	  if (entry === undefined) return { status: 'not_declared', name }
 72	  const resolution = await deps.resolver.resolve(entry.artifact)
 73	  if (resolution.status !== 'resolved') return { status: 'not_materializable', name, reason: resolution.reason }
 74	
 75	  const materialized = await materialize(entry.artifact, resolution.pinned, deps)
 76	  if (!materialized.ok) return { status: 'failed', name, stage: 'materialize', reason: materialized.reason, downloaded: false, installed: false }
 77	  const { downloaded } = materialized.value
 78	
 79	  const reconciled = await reconcileRuntime(name, materialized.value, deps.installer)
 80	  if (!reconciled.ok) return { status: 'failed', name, stage: 'install', reason: reconciled.reason, downloaded, installed: false }
 81	  const { installed, state } = reconciled.value
 82	
 83	  const evidence = { catalogSha256: entry.artifact.sha256, materializedSha256: materialized.value.sha256, runtimeSha256: state?.contentSha256 ?? '' }
 84	  if (!isReady(evidence)) return { status: 'failed', name, stage: 'verify', reason: mismatchReason(name, evidence), downloaded, installed }
 85	  return { status: 'ready', name, evidence, downloaded, installed }
 86	}
 87	
 88	async function materialize(artifact: CatalogArtifact, pinned: PinnedModelArtifact, deps: EnsureModelDependencies): Promise<StepResult<Materialized>> {
 89	  const outcome = await materializeArtifact({ artifact, pinned, cacheDir: deps.cacheDir, fetcher: deps.fetcher })
 90	  if ('reason' in outcome) return { ok: false, reason: outcome.reason }
 91	  // `materializeArtifact` sólo devuelve `cached`/`fetched` tras medir el
 92	  // sha256 del archivo publicado: ese es el digest materializado.
 93	  return { ok: true, value: { path: outcome.path, sha256: outcome.sha256, downloaded: outcome.status === 'fetched' } }
 94	}
 95	
 96	/** Instala sólo si el runtime no resuelve el nombre al contenido materializado, y vuelve a inspeccionar. */
 97	async function reconcileRuntime(name: string, materialized: Materialized, installer: ModelInstaller): Promise<StepResult<Reconciled>> {
 98	  const current = await installer.inspect(name)
 99	  if (servesContent(current, materialized.sha256)) return { ok: true, value: { state: current, installed: false } }
100	  const outcome = await installer.install({ name, artifactPath: materialized.path, contentSha256: materialized.sha256 })
101	  if (outcome.status !== 'installed') return { ok: false, reason: outcome.reason }
102	  return { ok: true, value: { state: await installer.inspect(name), installed: true } }
103	}
104	
105	function servesContent(state: InstalledModelState | undefined, sha256: string): boolean {
106	  return state?.contentSha256 === sha256
107	}
108	
109	function isReady(evidence: ReadinessEvidence): boolean {
110	  return evidence.catalogSha256 === evidence.materializedSha256 && evidence.materializedSha256 === evidence.runtimeSha256
111	}
112	
113	function mismatchReason(name: string, evidence: ReadinessEvidence): string {
114	  const runtime = evidence.runtimeSha256 === '' ? 'nada' : `sha256:${evidence.runtimeSha256}`
115	  return `${name}: el catálogo declara sha256:${evidence.catalogSha256}, la caché tiene sha256:${evidence.materializedSha256} y el runtime resuelve ${runtime}`
116	}
117	/**
118	 * Materialización verificada de un artefacto de modelo en la caché local
119	 * (TASK-THYROX-0729).
120	 *
121	 * La caché es reconstruible y no es autoridad: la autoridad es el artefacto
122	 * permanente, y el contenido válido es el que tiene el sha256 que el catálogo
123	 * declara. Por eso una entrada en caché se vuelve a verificar antes de usarla,
124	 * y una que no coincide se descarta y se reconstruye.
125	 *
126	 * La descarga escribe en un temporal hermano y sólo un `rename` atómico tras
127	 * verificar el sha256 la publica en la ruta por digest que leen los
128	 * consumidores: una descarga cortada o con otro contenido nunca parece un
129	 * GGUF materializado. Quién descarga es un `ArtifactFetcher`: en producción,
130	 * un trabajo de la primitiva de Podman sin credencial.
131	 */
132	import { mkdir, rename, rm, stat } from 'node:fs/promises'
133	import { join } from 'node:path'
134	
135	import type { CatalogArtifact } from '@thyrox/model-artifacts/catalogEntry.ts'
136	import type { PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'
137	
138	import { sha256OfFile } from './sha256File.js'
139	
140	export type FetchOutcome =
141	  | { readonly status: 'fetched' }
142	  | { readonly status: 'failed'; readonly reason: string }
143	
144	/** Escribe el blob GGUF de `pinned` en `destination`; no verifica ni publica nada. */
145	export interface ArtifactFetcher {
146	  fetch(pinned: PinnedModelArtifact, destination: string): Promise<FetchOutcome>
147	}
148	
149	export type MaterializationOutcome =
150	  | { readonly status: 'cached' | 'fetched'; readonly path: string; readonly sha256: string }
151	  | { readonly status: 'rejected' | 'failed'; readonly reason: string }
152	
153	export interface MaterializationRequest {
154	  readonly artifact: CatalogArtifact
155	  readonly pinned: PinnedModelArtifact
156	  readonly cacheDir: string
157	  readonly fetcher: ArtifactFetcher
158	}
159	
160	/** La única ruta que un consumidor lee: el GGUF verificado, nombrado por su contenido. */
161	export function cachedArtifactPath(cacheDir: string, sha256: string): string {
162	  return join(cacheDir, `sha256-${sha256}.gguf`)
163	}
164	
165	/** El sha256 medido del archivo, o `undefined` si no existe. */
166	async function measuredSha256(path: string): Promise<string | undefined> {
167	  try {
168	    await stat(path)
169	  } catch {
170	    return undefined
171	  }
172	  return sha256OfFile(path)
173	}
174	
175	export async function materializeArtifact(request: MaterializationRequest): Promise<MaterializationOutcome> {
176	  const { artifact, pinned, cacheDir } = request
177	  if (pinned.blobDigest !== `sha256:${artifact.sha256}`) {
178	    return { status: 'rejected', reason: `el artefacto fijado apunta a ${pinned.blobDigest}, no al contenido sha256:${artifact.sha256} del catálogo` }
179	  }
180	  const path = cachedArtifactPath(cacheDir, artifact.sha256)
181	  // El sha256 que se devuelve es el MEDIDO sobre el archivo, no el declarado:
182	  // es la segunda igualdad de READY y no puede ser una copia del catálogo.
183	  const cached = await measuredSha256(path)
184	  if (cached === artifact.sha256) return { status: 'cached', path, sha256: cached }
185	
186	  await mkdir(cacheDir, { recursive: true })
187	  await rm(path, { force: true })
188	  const partial = join(cacheDir, `.partial-${artifact.sha256}-${process.pid}-${Date.now()}`)
189	  try {
190	    const fetched = await request.fetcher.fetch(pinned, partial)
191	    if (fetched.status !== 'fetched') return { status: 'failed', reason: fetched.reason }
192	    const actual = await sha256OfFile(partial)
193	    if (actual !== artifact.sha256) return { status: 'rejected', reason: `se descargó sha256:${actual}, el catálogo declara sha256:${artifact.sha256}` }
194	    await rename(partial, path)
195	    return { status: 'fetched', path, sha256: actual }
196	  } finally {
197	    await rm(partial, { force: true })
198	  }
199	}
200	/** Digests de archivos grandes por streaming, sin cargarlos enteros en memoria. */
201	import { createHash, type Hash } from 'node:crypto'
202	import { createReadStream } from 'node:fs'
203	
204	/** Alimenta `hash` con el contenido de `path` y devuelve su digest en hex. */
205	export function hashFile(path: string, hash: Hash): Promise<string> {
206	  return new Promise((resolve, reject) => {
207	    createReadStream(path)
208	      .on('data', chunk => hash.update(chunk))
209	      .on('error', reject)
210	      .on('end', () => resolve(hash.digest('hex')))
211	  })
212	}
213	
214	export function sha256OfFile(path: string): Promise<string> {
215	  return hashFile(path, createHash('sha256'))
216	}
